const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const shuffle=a=>{const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x};
const fillSequence=(bank,count)=>{let out=[];while(out.length<count)out.push(...shuffle(bank));return out.slice(0,count)};
const escapeHtml=s=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));

$$('[data-open]').forEach(b=>b.addEventListener('click',()=>openView(b.dataset.open)));
$$('.back').forEach(b=>b.addEventListener('click',()=>openView('home')));
function openView(id){$$('.view').forEach(v=>v.classList.remove('active'));$('#'+id).classList.add('active');window.scrollTo({top:0,behavior:'smooth'})}
$('#fullscreenBtn').addEventListener('click',async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen()}catch(e){}});
document.addEventListener('fullscreenchange',()=>$('#fullscreenBtn').textContent=document.fullscreenElement?'Exit Full Screen':'Full Screen');

