const wfPattern=$('#wfPattern');Object.keys(wordFlashBanks).forEach(k=>wfPattern.add(new Option(k,k)));
let wf={seq:[],i:0,t:null,paused:false,phase:'ready'};
$('#wfMode').addEventListener('change',()=>$('#wfAutoOptions').classList.toggle('hidden',$('#wfMode').value!=='auto'));
$('#wfStart').addEventListener('click',startWF);$('#wfRestart').addEventListener('click',startWF);$('#wfPause').addEventListener('click',()=>{wf.paused=!wf.paused;clearTimeout(wf.t);$('#wfPause').textContent=wf.paused?'Resume':'Pause';if(!wf.paused)wfAutoWord()});
$('#wfAction').addEventListener('click',()=>{if(wf.phase==='show'){wf.phase='hide';$('#wfWord').textContent='';$('#wfPrompt').textContent='Think. Read it in your head.';$('#wfAction').textContent='Reveal'}else if(wf.phase==='hide'){wf.phase='reveal';$('#wfWord').textContent=wf.seq[wf.i];$('#wfPrompt').textContent='Read it again.';$('#wfAction').textContent='Next Word'}else{wf.i++;wf.phase='show';if(wf.i>=wf.seq.length)return wfDone();wfGuidedWord()}});
function startWF(){clearTimeout(wf.t);wf.seq=fillSequence(wordFlashBanks[wfPattern.value],Number($('#wfCount').value));wf.i=0;wf.paused=false;$('#wfPause').textContent='Pause';$('#wfRestart').classList.remove('hidden');if($('#wfMode').value==='auto'){wfAutoWord()}else{wf.phase='show';wfGuidedWord()}}
function wfGuidedWord(){setCounter('#wfCounter',wf.i,wf.seq.length);$('#wfWord').textContent=wf.seq[wf.i];$('#wfPrompt').textContent='Read the word.';$('#wfAction').textContent='Hide';$('#wfAction').classList.remove('hidden');$('#wfPause').classList.add('hidden')}
function wfAutoWord(){if(wf.paused)return;if(wf.i>=wf.seq.length)return wfDone();setCounter('#wfCounter',wf.i,wf.seq.length);$('#wfWord').textContent=wf.seq[wf.i];$('#wfPrompt').textContent='';$('#wfAction').classList.add('hidden');$('#wfPause').classList.remove('hidden');wf.t=setTimeout(()=>{$('#wfWord').textContent='';wf.t=setTimeout(()=>{wf.i++;wfAutoWord()},Number($('#wfBlankTime').value))},Number($('#wfWordTime').value))}
function wfDone(){clearTimeout(wf.t);$('#wfWord').textContent='Complete';$('#wfPrompt').textContent='';$('#wfAction').classList.add('hidden');$('#wfPause').classList.add('hidden');$('#wfCounter').textContent=`${wf.seq.length} words`}

