$('#hfAction').addEventListener('click',()=>{const item=hf.seq[hf.i];if(hf.phase==='show'){hf.phase='hide';$('#hfWord').textContent='';$('#hfMap').classList.add('hidden');$('#hfPrompt').textContent='Read it in your head.';$('#hfAction').textContent='Reveal'}else if(hf.phase==='hide'){hf.phase='reveal';$('#hfWord').textContent=item[0];if($('#hfMapping').checked)renderSoundMap(item[1]);$('#hfPrompt').textContent=$('#hfMapping').checked?'Connect the sounds to the spelling.':'Read the word again.';$('#hfAction').textContent='Next Word'}else{hf.i++;hf.phase='show';if(hf.i>=hf.seq.length)return hfDone();hfGuidedWord()}});
function startHF(){clearTimeout(hf.t);hf.seq=fillSequence(hfData[$('#hfSet').value],Number($('#hfCount').value));hf.i=0;hf.paused=false;$('#hfPause').textContent='Pause';$('#hfRestart').classList.remove('hidden');if($('#hfMode').value==='auto')hfAutoWord();else{hf.phase='show';hfGuidedWord()}}
function hfGuidedWord(){setCounter('#hfCounter',hf.i,hf.seq.length);$('#hfWord').textContent=hf.seq[hf.i][0];$('#hfMap').classList.add('hidden');$('#hfPrompt').textContent='Read the word.';$('#hfAction').textContent='Hide';$('#hfAction').classList.remove('hidden');$('#hfPause').classList.add('hidden')}
function renderSoundMap(map){$('#hfMap').innerHTML=map.map(x=>`<div class="sound-box ${x[2]?'tricky':''}"><b>${escapeHtml(x[0])}</b><small>${escapeHtml(x[1])}</small></div>`).join('');$('#hfMap').classList.remove('hidden')}
function hfAutoWord(){if(hf.paused)return;if(hf.i>=hf.seq.length)return hfDone();setCounter('#hfCounter',hf.i,hf.seq.length);$('#hfWord').textContent=hf.seq[hf.i][0];$('#hfMap').classList.add('hidden');$('#hfPrompt').textContent='';$('#hfAction').classList.add('hidden');$('#hfPause').classList.remove('hidden');hf.t=setTimeout(()=>{$('#hfWord').textContent='';hf.t=setTimeout(()=>{hf.i++;hfAutoWord()},Number($('#hfBlankTime').value))},Number($('#hfWordTime').value))}
function hfDone(){clearTimeout(hf.t);$('#hfWord').textContent='Complete';$('#hfMap').classList.add('hidden');$('#hfPrompt').textContent='';$('#hfAction').classList.add('hidden');$('#hfPause').classList.add('hidden');$('#hfCounter').textContent=`${hf.seq.length} words`}

