const moSkill=$('#moSkill');
['Foundations','Affixes & Multisyllabic','Roots & Word Families','Transfer & Application'].forEach(g=>{const og=document.createElement('optgroup');og.label=g;Object.entries(morphologyBanks).filter(([,v])=>v.group===g).forEach(([k,v])=>og.append(new Option(v.label,k)));moSkill.append(og)});
let mo={seq:[],i:0,step:-1,t:null,paused:false,mode:'guided',cyclePhase:'word'};const stepNames=['SPOT','SPLIT','READ','BUILD','CHECK'];
$('#moMode').addEventListener('change',()=>$('#moCycleOptions').classList.toggle('hidden',$('#moMode').value!=='cycle'));
$('#moStart').addEventListener('click',startMo);$('#moRestart').addEventListener('click',startMo);$('#moNext').addEventListener('click',()=>{mo.i++;if(mo.i>=mo.seq.length)return moDone();mo.step=-1;moGuidedWord()});$('#moAction').addEventListener('click',()=>{if(mo.mode==='guided')moAdvance();else if(mo.cyclePhase==='reveal')moCycleNext()});$('#moPause').addEventListener('click',()=>{mo.paused=!mo.paused;clearTimeout(mo.t);$('#moPause').textContent=mo.paused?'Resume':'Pause';if(!mo.paused)moCycleWord()});
function startMo(){clearTimeout(mo.t);mo.mode=$('#moMode').value;mo.seq=fillSequence(morphologyBanks[moSkill.value].items,Number($('#moCount').value));mo.i=0;mo.step=-1;mo.paused=false;$('#moPause').textContent='Pause';$('#moRestart').classList.remove('hidden');if(mo.mode==='guided')moGuidedWord();else moCycleWord()}
function fitWord(el,text){el.textContent=text;const n=text.length;el.style.fontSize=n>18?'clamp(2.2rem,5.5vw,4.6rem)':n>13?'clamp(2.7rem,7vw,5.6rem)':''}
function resetMoButtons(){['#moAction','#moNext','#moPause'].forEach(s=>$(s).classList.add('hidden'))}
function activateMoStep(i){$$('#moSteps span').forEach((x,n)=>x.classList.toggle('active',n===i))}
function moGuidedWord(){resetMoButtons();activateMoStep(-1);const item=mo.seq[mo.i];fitWord($('#moWord'),item.w);$('#moVisual').innerHTML='';$('#moPrompt').textContent='What useful part do you notice?';$('#moAction').textContent='SPOT';$('#moAction').classList.remove('hidden');setCounter('#moCounter',mo.i,mo.seq.length)}
function moAdvance(){const item=mo.seq[mo.i];mo.step++;activateMoStep(mo.step);resetMoButtons();if(mo.step===0){fitWord($('#moWord'),item.w);renderChunks(item,item.spot);$('#moPrompt').textContent='SPOT: Notice a useful part, pattern, base, affix, or root.'}
 if(mo.step===1){$('#moWord').textContent='';renderChunks(item,item.parts.map((_,i)=>i),true);$('#moPrompt').textContent='SPLIT: Separate the useful parts so you can work with them.'}
 if(mo.step===2){$('#moWord').textContent='';$('#moVisual').innerHTML=`<div class="chunk-row">${item.parts.map((p,i)=>`${i?'<span class="read-arrow">→</span>':''}<span class="chunk">${escapeHtml(p)}</span>`).join('')}</div><div class="read-arrow" style="margin-top:12px">↓</div><div class="whole-small">${escapeHtml(item.w)}</div>`;$('#moPrompt').textContent='READ: Read the parts, then bring them back together and read the whole word smoothly.'}
 if(mo.step===3){$('#moWord').textContent='';$('#moVisual').innerHTML=`<div class="build-chain">${item.build.map((b,i)=>`${i?'<span class="read-arrow">→</span>':''}<span class="build-piece ${i===item.build.length-1?'final':''}">${escapeHtml(b)}</span>`).join('')}</div>`;$('#moPrompt').textContent='BUILD: Use the meaningful parts to build a reasonable meaning.'}
 if(mo.step===4){fitWord($('#moWord'),item.w);$('#moVisual').innerHTML=`<div class="sentence-card">${escapeHtml(item.check)}</div>`;$('#moPrompt').textContent='CHECK: Does the meaning fit? Reread the whole sentence.'}
 if(mo.step<4){$('#moAction').textContent=stepNames[mo.step+1];$('#moAction').classList.remove('hidden')}else $('#moNext').classList.remove('hidden')}
function renderChunks(item,highlight=[],showBars=false){$('#moVisual').innerHTML=`<div class="chunk-row">${item.parts.map((p,i)=>`${i&&showBars?'<span class="bar">|</span>':''}<span class="chunk ${highlight.includes(i)?'focus':''}">${escapeHtml(p)}</span>`).join('')}</div>`}
function moCycleWord(){if(mo.paused)return;if(mo.i>=mo.seq.length)return moDone();resetMoButtons();activateMoStep(-1);const item=mo.seq[mo.i];mo.cyclePhase='word';fitWord($('#moWord'),item.w);$('#moVisual').innerHTML='';$('#moPrompt').textContent='Read it.';$('#moPause').classList.remove('hidden');setCounter('#moCounter',mo.i,mo.seq.length);mo.t=setTimeout(moCycleThink,Number($('#moWordTime').value))}
function moCycleThink(){if(mo.paused)return;mo.cyclePhase='think';$('#moWord').textContent='';$('#moVisual').innerHTML='';$('#moPrompt').textContent='Where would you split it? What meaning can you build?';mo.t=setTimeout(moCycleReveal,Number($('#moThinkTime').value))}
function moCycleReveal(){if(mo.paused)return;const item=mo.seq[mo.i];mo.cyclePhase='reveal';fitWord($('#moWord'),item.w);$('#moVisual').innerHTML=`<div class="discussion-label">Split + Build</div><div class="chunk-row">${item.parts.map((p,i)=>`${i?'<span class="bar">|</span>':''}<span class="chunk focus">${escapeHtml(p)}</span>`).join('')}</div><div class="build-chain" style="margin-top:18px">${item.build.map((b,i)=>`${i?'<span class="read-arrow">→</span>':''}<span class="build-piece ${i===item.build.length-1?'final':''}">${escapeHtml(b)}</span>`).join('')}</div>`;$('#moPrompt').textContent='Discuss the split. Build the meaning. Reread the whole word.';const rt=$('#moRevealTime').value;if(rt==='teacher'){$('#moPause').classList.add('hidden');$('#moAction').textContent='Next Word';$('#moAction').classList.remove('hidden')}else{mo.t=setTimeout(moCycleNext,Number(rt))}}
function moCycleNext(){clearTimeout(mo.t);mo.i++;moCycleWord()}
function moDone(){clearTimeout(mo.t);resetMoButtons();activateMoStep(-1);$('#moWord').style.fontSize='';$('#moWord').textContent='Complete';$('#moVisual').innerHTML='';$('#moPrompt').textContent='';$('#moCounter').textContent=`${mo.seq.length} words`}
function setCounter(sel,i,n){$(sel).textContent=`Word ${i+1} of ${n}`}
